# Writes src/modeldata.js: the light character models (art/models/*.glb) by file name; build.mjs copies them to dist/models/lo_<name>.glb (inline in index_single). Usage: python3 tools/makemodels.py
import base64, os
D = os.path.join(os.path.dirname(__file__), '..', 'art', 'models'); out = []
for f in sorted(os.listdir(D)):
    if f.endswith('.glb'): b = open(os.path.join(D, f), 'rb').read(); out.append("  %s: 'models/lo_%s.glb'" % (f[:-4], f[:-4])); print(f, round(len(b) / 1024), 'KB')
open(os.path.join(os.path.dirname(__file__), '..', 'src', 'modeldata.js'), 'w').write('// generated by tools/makemodels.py from art/models/*.glb\n// LAG FIX Nov 19 (owner 11:40): the light (packed) character models are files beside index.html (dist/models/lo_<name>.glb, copied by build.mjs), fetched when a\n// character is made, instead of 8.5 MB of base64 inside the page; index_single.html carries them inside as data: addresses (build.mjs), so it still plays from a folder\nexport const MODELS = {\n' + ',\n'.join(out) + '\n};\n')
# the liteModel helper (LAG FIX Nov 19 12:45) follows the list
HELPER = "import { CONFIG } from './config.js';\n// LAG FIX Nov 19 12:45: a light model as an ArrayBuffer. Over http(s), or a data: address (index_single.html), it is fetched; a page opened from a folder (file://)\n// cannot fetch, so it loads the model's script twin (dist/models/lo_<name>.js, written by build.mjs: it puts the base64 in window.__LOMODELS) with a script tag.\nexport function liteModel(key) {\n  const src = MODELS[key]; if (!src) return Promise.reject(new Error('no model ' + key));\n  const viaScript = () => new Promise((ok, no) => { const B = window.__LOMODELS || (window.__LOMODELS = {}); const done = () => { const b = B[key]; if (!b) { no(new Error('no model ' + key)); return; } ok(Uint8Array.from(atob(b), (c) => c.charCodeAt(0)).buffer); };\n    if (B[key]) { done(); return; } const sc = document.createElement('script'); sc.src = src.replace(/\\.glb$/, '.js'); sc.onload = done; sc.onerror = () => no(new Error('no model ' + key)); document.head.appendChild(sc); });\n  if (!src.startsWith('data:') && location.protocol === 'file:') return viaScript();\n  // (owner 13:10, premortem G) a failed fetch over http is tried again (CONFIG.lag.modelRetry: n more times, ms apart, growing), then the script twin; a model that\n  // never loads leaves the person's plain stand-in figure in place (src/people.js), never an empty spot\n  const R = (CONFIG.lag && CONFIG.lag.modelRetry) || { n: 0, ms: 0 };\n  const get = (k) => fetch(src).then((r) => { if (!r.ok) throw new Error('no file'); return r.arrayBuffer(); }).catch((e) => (src.startsWith('data:') ? Promise.reject(e) : k < R.n ? new Promise((ok) => setTimeout(ok, R.ms * (k + 1))).then(() => get(k + 1)) : viaScript()));\n  return get(0);\n}\n"
open(os.path.join(os.path.dirname(__file__), '..', 'src', 'modeldata.js'), 'a').write(HELPER)
